static void Main(string[] args)
{
    int n = 5, x = 4, z, c, k;
    for (c = 1; c <= n; c++)
    {
        for (k = 1; k <= c; k++)
        {
            z = 3 * x * x + 2 * x + 4 / x + 8;
            Console.Write((char)z);
        }
        Console.WriteLine();
    }
}

static void Main(string[] args)
{
    int n = 5, x = 4, z, c, k;
    z = 3 * x * x + 2 * x + 4 / x + 8; // z = 65
    for (c = 1; c <= n; c++)
    {
        for (k = 1; k <= c; k++)
        {
            Console.Write((char)z);
            z++;
        }
        Console.WriteLine();
    }
}

